 55	    @KafkaListener(
 56	            topics = "order-processing-topic",
 57	            groupId = "order-processing-group",
 58	            containerFactory = "orderProcessingKafkaListenerContainerFactory"
 59	    )
 60	    @Transactional
 61	    public void handleOrderProcessingEvent(
 62	            @Payload OrderProcessingEvent event,
 63	            Acknowledgment acknowledgment) {
 64	
 65	        Instant start = Instant.now();
 66	
 67	        try {
 68	            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
 69	                    event.getOrderId(), event.getEventId());
 70	
 71	            // 1. 멱등성 검사 - 이미 처리된 주문인지 확인
 72	            if (isOrderAlreadyProcessed(event.getOrderId())) {
 73	                log.warn("이미 처리된 주문 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
 74	                acknowledgment.acknowledge();
 75	                return;
 76	            }
 77	
 78	            // 2. 주문 및 사용자 정보 조회
 79	            Order order = orderRepository.findById(event.getOrderId())
 80	                    .orElseThrow(() -> new IllegalArgumentException(
 81	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
 82	
 83	            User user = userQueryService.findByEmail(event.getUserEmail());
 84	
 85	            // 3. 권한 확인
 86	            if (!order.getUser().getId().equals(user.getId())) {
 87	                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
 88	                        event.getOrderId(), order.getUser().getId(), user.getId());
 89	                throw new IllegalArgumentException("주문과 사용자 정보가 일치하지 않습니다.");
 90	            }
 91	
 92	            // 4. 전체 주문 처리 수행 (하나의 트랜잭션)
 93	            processCompleteOrder(order, user, event.getRequestDto());
 94	
 95	            // 5. 성공 알림 전송
 96	            sendSuccessNotification(event.getOrderId(), event.getUserEmail());
 97	
 98	            // 6. 처리 완료 ACK
 99	            acknowledgment.acknowledge();
100	
101	            // 처리 시간 로깅
102	            Instant end = Instant.now();
103	            Duration duration = Duration.between(start, end);
104	            log.info("주문 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
105	
106	        } catch (Exception e) {
107	            log.error("주문 처리 실패: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
108	            handleOrderProcessingFailure(event, e, acknowledgment);
109	        }
110	    }
111	
112	    /**
113	     * 주문 재시도 이벤트 리스너
114	     */
115	    @KafkaListener(
116	            topics = "order-retry-topic",
117	            groupId = "order-retry-group",
118	            containerFactory = "orderProcessingKafkaListenerContainerFactory"
119	    )
120	    @Transactional
121	    public void handleOrderRetryEvent(
122	            @Payload OrderProcessingEvent event,
123	            Acknowledgment acknowledgment) {
124	
125	        try {
126	            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
127	                    event.getOrderId(), event.getRetryCount());
128	
129	            if (event.isMaxRetryExceeded()) {
130	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
131	                        event.getOrderId(), event.getRetryCount());
132	
133	                // 최종 실패 알림
134	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
135	                acknowledgment.acknowledge();
136	                return;
137	            }
138	
139	            // 멱등성 재확인
140	            if (isOrderAlreadyProcessed(event.getOrderId())) {
141	                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
142	                acknowledgment.acknowledge();
143	                return;
144	            }
145	
146	            // 재시도 지연 (백오프 전략)
147	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
148	
149	            // 주문 재처리
150	            handleOrderProcessingEvent(event, acknowledgment);
151	
152	        } catch (InterruptedException e) {
153	            Thread.currentThread().interrupt();
154	            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
155	            acknowledgment.acknowledge();
156	        } catch (Exception e) {
157	            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
158	                    event.getOrderId(), e.getMessage(), e);
159	            acknowledgment.acknowledge();
160	        }
161	    }
162	
163	    /**
164	     * 전체 주문 처리 수행 (하나의 트랜잭션)
165	     */
166	    private void processCompleteOrder(Order order, User user, PayAndShipmentRequestDto requestDto) {
167	        try {
168	            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());
169	
170	            // 1. 결제 처리
171	            Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
172	            order.assignPayment(payment);
173	
174	            if (!payment.isSuccess()) {
175	                throw new RuntimeException("결제 실패: " + payment.getStatus());
176	            }
177	
178	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());
179	
180	            // 2. 배송 정보 생성
181	            OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
182	                    order,
183	                    requestDto.getReceiverName(),
184	                    requestDto.getReceiverPhone(),
185	                    requestDto.getPostalCode(),
186	                    requestDto.getAddress()
187	            );
188	            order.assignOrderShipment(shipment);
189	            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());
190	
191	            // 3. 상태 업데이트 (OrderStatus enum 사용)
192	            if (!order.getStatus().canTransitionTo(OrderStatus.PAYMENT_COMPLETED)) {
193	                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
194	            }
195	            order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
196	
197	            if (requestDto.isWarehouseStorage()) {
198	                // 창고 보관일 경우
199	                WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
200	                order.assignWarehouseStorage(warehouseStorage);
201	
202	                // 상태 전환 검증
203	                if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
204	                    order.updateStatus(OrderStatus.PREPARING);
205	                }
206	                if (order.getStatus().canTransitionTo(OrderStatus.IN_WAREHOUSE)) {
207	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
208	                }
209	                if (order.getStatus().canTransitionTo(OrderStatus.COMPLETED)) {
210	                    order.updateStatus(OrderStatus.COMPLETED);
211	                }
212	
213	                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
214	            } else {
215	                // 실제 배송일 경우
216	                if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
217	                    order.updateStatus(OrderStatus.PREPARING);
218	                }
219	                log.info("배송 준비 완료: 주문ID={}", order.getId());
220	            }
221	
222	            // 4. 주문 저장
223	            orderRepository.save(order);
224	            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());
225	
226	        } catch (Exception e) {
227	            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
228	            throw e; // 트랜잭션 롤백을 위해 예외 재발생
229	        }
230	    }
231	
232	    /**
233	     * 주문이 이미 처리되었는지 확인 (멱등성 보장)
234	     */
235	    private boolean isOrderAlreadyProcessed(Long orderId) {
236	        try {
237	            Order order = orderRepository.findById(orderId).orElse(null);
238	            if (order == null) {
239	                return false;
240	            }
241	
242	            // PENDING_PAYMENT 상태가 아니면 이미 처리된 것으로 간주
243	            OrderStatus currentStatus = order.getStatus();
244	            return currentStatus != OrderStatus.PENDING_PAYMENT;
245	
246	        } catch (Exception e) {
247	            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
248	            return false;
249	        }
250	    }
251	
252	    /**
253	     * 주문 처리 실패 처리
254	     */
255	    private void handleOrderProcessingFailure(OrderProcessingEvent event, Exception error, Acknowledgment acknowledgment) {
256	        try {
257	            // 재시도 가능한 오류인지 판단
258	            if (isRetryableError(error)) {
259	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
260	                orderEventProducer.sendOrderRetryEvent(event);

